style.css:
/* Hide the Google logo */
img[alt="Google"] {
    display: none !important;
}

/* Add your name at the top */
body::before {
    content: "AJISH";
    display: block;
    font-size: 60px;
    font-family: Arial, sans-serif;
    font-weight: bold;
    text-align: center;
    margin-top: 100px;
    color: #4285f4; /* Google blue */
}
